                  lambda label: set(_tokens(want)) <= set(_tokens(label)),
                  lambda label: set(_tokens(want)) & _NONE_WORDS and set(_tokens(label)) & _NONE_WORDS):
        hits = [v for v, label in options if match(label)]
        if len(hits) == 1:
            return hits[0]
    return None


